import{_ as d,o as r,a as e,b as a}from"./app.DKoEZOcr.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"附录","link":"/api/appendix/appendix"},{"text":"Reg矢量计算接口精度标准汇总","link":"/api/appendix/reg_vector_compute_interface_precision_standard_summary"}]},"headers":[],"relativePath":"api/appendix/reg_vector_compute_interface_precision_standard_summary.md","filePath":"api/appendix/reg_vector_compute_interface_precision_standard_summary.md","lastUpdated":1785986301000}'),p={name:"api/appendix/reg_vector_compute_interface_precision_standard_summary.md"};function o(s,t,l,u,n,i){return r(),e("div",null,[...t[0]||(t[0]=[a('<div><article class="markdown-body"><h1>Reg矢量计算接口精度标准汇总<span id="reg-vector-precision-summary"></span></h1><p>本节汇总介绍了Reg矢量计算接口精度标准的情况，本节内容仅针对如下型号生效：</p><p>Ascend 950PR/Ascend 950DT</p><p><strong>表 1</strong> Reg矢量计算API精度标准<a id="table-precision-standard"></a></p><table><thead><tr><th>接口类型</th><th>接口</th><th>硬件指令精度标准</th><th>软仿精度标准</th></tr></thead><tbody><tr><td>基础算术</td><td>Exp</td><td>1ulp, not support denormalized numbers</td><td>1ulp, support denormalized numbers</td></tr><tr><td>基础算术</td><td>Sqrt</td><td>1ulp, not support denormalized numbers</td><td>• float: 0ulp <br>• half/float: 1ulp, support denormalized numbers</td></tr><tr><td>基础算术</td><td>Add</td><td>• half/float: 0ulp, support denormalized numbers<br>• bfloat16_t: Add(x, y) = rint_to_bf16(Add(cast_to_f32(x), cast_to_f32(y)))</td><td>0ulp, support denormalized numbers</td></tr><tr><td>基础算术</td><td>Sub</td><td>Sub(x, y) = Add(x, Neg(y))</td><td>0ulp, support denormalized numbers</td></tr><tr><td>基础算术</td><td>Adds</td><td>• half/float: 0ulp, support denormalized numbers<br>• bfloat16_t: Add(x, y) = rint_to_bf16(Add(cast_to_f32(x), cast_to_f32(y)))</td><td>0ulp, support denormalized numbers</td></tr><tr><td>基础算术</td><td>Div</td><td>1ulp, not support denormalized numbers</td><td>• complex64: 0ulp, not support denormalized numbers <br>• float: 0ulp, support denormalized numbers <br>• half/float: 1ulp, support denormalized numbers</td></tr><tr><td>基础算术</td><td>Neg</td><td>符号位取反</td><td>-</td></tr><tr><td>基础算术</td><td>Ln/Log</td><td>1ulp, not support denormalized numbers</td><td>1ulp, support denormalized numbers</td></tr><tr><td>基础算术</td><td>Log2/Log10</td><td>-</td><td>• 1ulp, not support denormalized numbers<br>• 1ulp, support denormalized numbers</td></tr><tr><td>基础算术</td><td>Mul</td><td>• half/float: 0ulp, support denormalized numbers<br>• bfloat16_t: Mul(x, y) = rint_to_bf16(Mul(cast_to_f32(x), cast_to_f32(y)))</td><td>-</td></tr><tr><td>基础算术</td><td>Muls</td><td>half/float: 0ulp, support denormalized numbers</td><td>-</td></tr><tr><td>复合指令</td><td>AbsSub</td><td>指令串行，AbsSub(x) = Abs(Sub(x))</td><td>-</td></tr><tr><td>复合指令</td><td>ExpSub</td><td>• 输入half，输出float：<br>ExpSub(x, y) = Exp(Sub(cast_to_f32(x), cast_to_f32(y)))<br>• 输入float，输出float：<br>ExpSub(x, y) = Exp(Sub(x, y))</td><td>-</td></tr><tr><td>复合指令</td><td>Axpy</td><td>结果等效于：乘累加采用高精度计算, 同比Fma(x, y, z)</td><td>-</td></tr><tr><td>复合指令</td><td>MulDstAdd</td><td>结果等效于：乘累加采用高精度计算，同比Fma(x, y, z)</td><td>-</td></tr><tr><td>复合指令</td><td>MulAddDst</td><td>结果等效于：乘累加采用高精度计算，同比Fma(x, y, z)</td><td>-</td></tr><tr><td>复合指令</td><td>MulsCast</td><td>MulsCast(x, y) = cast_to_f16&lt;roundingmode&gt;(x * y)</td><td>-</td></tr><tr><td>归约计算</td><td>Reduce</td><td>half/float: 0ulp, 采用二叉树结构的成对累加策略</td><td>-</td></tr><tr><td>归约计算</td><td>ReduceDataBlock</td><td>half/float: 0ulp, 采用二叉树结构的成对累加策略</td><td>-</td></tr><tr><td>归约计算</td><td>PairReduceElem</td><td>half/float: 0ulp</td><td>-</td></tr></tbody></table><p><strong>表 2</strong> Vector低精度指令支持情况<a id="table-low-precision"></a></p><table><thead><tr><th>数据类型</th><th>接口</th></tr></thead><tbody><tr><td>fp4x2_e2m1_t</td><td>Cast、Duplicate（软仿）</td></tr><tr><td>fp4x2_e1m2_t</td><td>Cast、Duplicate（软仿）</td></tr><tr><td>fp8_e5m2_t</td><td>Cast、Duplicate（软仿）</td></tr><tr><td>fp8_e4m3fn_t</td><td>Cast、Duplicate（软仿）</td></tr><tr><td>fp8_e8m0_t</td><td>Cast、Duplicate（软仿）</td></tr><tr><td>hifloat8_t</td><td>Cast、Duplicate（软仿）</td></tr><tr><td>int4x2_t</td><td>Cast</td></tr><tr><td>int8_t</td><td>Cast、Add、Sub、Max、Min、Compare、Abs、Neg、Adds、Muls、Maxs、Mins、Compares、Duplicate</td></tr><tr><td>uint8_t</td><td>Cast、Add、Sub、Max、Min、Compare、Adds、Muls、Maxs、Mins、Compares、Duplicate</td></tr></tbody></table></article></div>',1)])])}const c=d(p,[["render",o]]);export{m as __pageData,c as default};
